// tidal-fields — ambient in C натуральный звукоряд, 66 BPM. Generated by MathMusic (style ambient, seed 2):
// first light → drift → bloom → tide → dusk → silence.
// 6 loops, each going round in its own time: 37, 31.25, 17, 34.5, 25.75, 20.5 beats. They share no common
// measure: together they repeat only after their least common multiple, 22910302875 beats (660 years at this tempo) —
// so the notes meet in ever new constellations ("Music for Airports": tape loops of different lengths).
// The scale: the harmonic series — overtones 8–15 of C: 0 204 386 551 702 841 969 1088 ¢ (the 7th harmonic
// 31 ¢ below the tempered minor seventh, the 11th between F and F♯); the low drone is that fundamental.
// x is time in beats; n counts semitones from C4 (fractional n are the harmonic series' own pitches).
import { TAU, delay, filter, floor, hz, noise, osc, reverb, sin, smooth } from '../src/engine.js'
import {
  VOWELS, blend, celestaTone, choir, fm, organ, pan, pianoTone, poly, strings,
} from '../src/instruments.js'

const SECTIONS = [[0,"first light"],[32,"drift"],[72,"bloom"],[120,"tide"],[152,"dusk"],[176,"silence"]]
const END = 200
const C4 = 440 * 2 ** (-9 / 12) // 261.63 Hz
// ---- the loops: each note [offset in the loop, n from C4, length] sounds again every `period` beats while from ≤ x < to
const LOOPS = [
  { period: 37, from: 0, to: 192, inst: 'piano', vel: 0.585, pan: -0.32, notes: [[2.75,0,3]] },
  { period: 31.25, from: 6, to: 177, inst: 'bells', vel: 0.4929, pan: -0.08, notes: [[0.5,24,3]] },
  { period: 17, from: 33, to: 181, inst: 'glass', vel: 0.4604, pan: 0.5, notes: [[2.75,14.04,5],[6,21.69,5],[7.75,27.86,6]] },
  { period: 34.5, from: 37, to: 156, inst: 'piano', vel: 0.4788, pan: -0.48, notes: [[1.5,14.04,5],[6,20.41,5],[8.75,0,4]] },
  { period: 25.75, from: 75, to: 157, inst: 'choir', vel: 0.7337, pan: -0.53, notes: [[0.5,-4.98,10]] },
  { period: 20.5, from: 79, to: 122, inst: 'bells', vel: 0.6483, pan: -0.21, notes: [[1.25,20.41,3]] },
]
// the notes of the loops of one instrument struck at x: [loop, note, cycle, start]
function strikes(inst, x) {
  const out = []
  LOOPS.forEach((l, i) => {
    if (l.inst !== inst || x < l.from || x >= l.to + 12) return
    l.notes.forEach(([o, n, d], j) => {
      const k = floor((x - l.from - o) / l.period), s = l.from + o + k * l.period
      if (k >= 0 && s < l.to && x - s < d + 6) out.push({ i, j, k, s, n, d, vel: l.vel, pan: l.pan })
    })
  })
  return out
}
// the pad's chord per section: [start, length, n…]
const PAD = [[0,32,[-12,-4.98,3.86,2.04]],[32,40,[-12,-4.98,3.86,2.04]],[72,48,[-12,-4.98,3.86,2.04]],[120,32,[-6.49,-1.12,8.41,7.02]],[152,24,[-12,-4.98,3.86,2.04]],[176,16,[-12,-4.98,3.86,2.04]]]
const padAt = x => { for (const p of PAD) if (x >= p[0] && x < p[0] + p[1]) return p; return null }
const DRONE = -36 // the low drone: the fundamental of the overtones

// ---- piano -------------------------------------------------------------------------------------
const track0 = {
  color: '#ffffff',
  graph: x => { const s = strikes('piano', x).filter(e => x - e.s < e.d); return s.length ? s.map(e => 0.4 + (e.n + 12) * 0.04) : null },
  midi: x => strikes('piano', x).filter(e => x - e.s < e.d * 0.9).map(e => 60 + Math.round(e.n * 100) / 100),
  formula: ["\\text{петли: } \\sum_i \\sum_j T\\big(f_{ij},\\ x - o_{ij} - p_i\\lfloor (x - o_{ij})/p_i \\rfloor\\big),\\quad p_i \\in \\{37, 34.5\\}","T \\text{ — рояль (тихо, педаль); НОК периодов — 22910302875 долей}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly(pianoTone, { release: 2, life: 9, max: 16 }), seen = new Set(), echo = delay({ time: sec * 1.5, feedback: 0.45, wet: 0.3 }), verb = reverb({ room: 0.95, damp: 0.3, wet: 0.6 })
    return x => {
      for (const e of strikes('piano', x)) {
        const id = e.i * 1e6 + e.j * 1e4 + e.k
        if (x >= e.s && !seen.has(id)) { seen.add(id); p.hit(hz(e.n, C4), e.vel, e.d * sec) }
      }
      return verb(...echo(...pan(0.85 * p(), 0.2 * sin(TAU * x / 37))))
    }
  },
}

// ---- bells -------------------------------------------------------------------------------------
const track1 = {
  color: '#fff3b0',
  graph: x => { const s = strikes('bells', x).filter(e => x - e.s < e.d); return s.length ? s.map(e => 1.2 + (e.n + 12) * 0.04) : null },
  midi: x => strikes('bells', x).filter(e => x - e.s < e.d * 0.9).map(e => 60 + Math.round(e.n * 100) / 100),
  formula: ["\\text{петли: } \\sum_i \\sum_j T\\big(f_{ij},\\ x - o_{ij} - p_i\\lfloor (x - o_{ij})/p_i \\rfloor\\big),\\quad p_i \\in \\{31.25, 20.5\\}","T \\text{ — FM-колокольчик; НОК периодов — 22910302875 долей}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly((f, t, v) => v * fm(f, t, { ratio: 3.5, index: 1.4, decay: 0.7, idecay: 3 }), { release: 2, life: 9, max: 16 }), seen = new Set(), echo = delay({ time: sec * 1.5, feedback: 0.45, wet: 0.3 }), verb = reverb({ room: 0.95, damp: 0.3, wet: 0.6 })
    return x => {
      for (const e of strikes('bells', x)) {
        const id = e.i * 1e6 + e.j * 1e4 + e.k
        if (x >= e.s && !seen.has(id)) { seen.add(id); p.hit(hz(e.n, C4), e.vel, e.d * sec) }
      }
      return verb(...echo(...pan(0.85 * p(), 0.2 * sin(TAU * x / 37))))
    }
  },
}

// ---- glass -------------------------------------------------------------------------------------
const track2 = {
  color: '#b8f0ff',
  graph: x => { const s = strikes('glass', x).filter(e => x - e.s < e.d); return s.length ? s.map(e => 1.6 + (e.n + 12) * 0.04) : null },
  midi: x => strikes('glass', x).filter(e => x - e.s < e.d * 0.9).map(e => 60 + Math.round(e.n * 100) / 100),
  formula: ["\\text{петли: } \\sum_i \\sum_j T\\big(f_{ij},\\ x - o_{ij} - p_i\\lfloor (x - o_{ij})/p_i \\rfloor\\big),\\quad p_i \\in \\{17\\}","T \\text{ — челеста; НОК периодов — 22910302875 долей}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly(celestaTone, { release: 2, life: 9, max: 16 }), seen = new Set(), echo = delay({ time: sec * 1.5, feedback: 0.45, wet: 0.3 }), verb = reverb({ room: 0.95, damp: 0.3, wet: 0.6 })
    return x => {
      for (const e of strikes('glass', x)) {
        const id = e.i * 1e6 + e.j * 1e4 + e.k
        if (x >= e.s && !seen.has(id)) { seen.add(id); p.hit(hz(e.n, C4), e.vel, e.d * sec) }
      }
      return verb(...echo(...pan(0.95 * p(), 0.2 * sin(TAU * x / 37))))
    }
  },
}

// ---- choir -------------------------------------------------------------------------------------
const track3 = {
  color: '#e0c8ff',
  graph: x => { const s = strikes('choir', x).filter(e => x - e.s < e.d); return s.length ? s.map(e => -0.8 + (e.n + 24) * 0.04) : null },
  midi: x => strikes('choir', x).filter(e => x - e.s < e.d * 0.9).map(e => 60 + Math.round(e.n * 100) / 100),
  formula: ["Ch = \\sum_{i} \\tfrac{G_i}{Q_i}\\BP_{F_i}\\big(\\saw f\\big),\\quad F:\\ \\text{«а» → «о» — хор, долгие ноты петель}"],
  audio({ bpm }) {
    const sec = 60 / bpm, c = choir({ voices: 2, size: 1, gain: 0.3 }), verb = reverb({ room: 0.95, damp: 0.3, wet: 0.6 }), level = smooth(600)
    return x => {
      const s = strikes('choir', x).filter(e => x >= e.s && x - e.s < e.d)
      const a = level(s.length ? 1 : 0), F = blend(VOWELS.a, VOWELS.o, 0.5 + 0.5 * sin(TAU * x / 32))
      const [l, r] = c(s.map(e => hz(e.n, C4)), F)
      return verb(1.6 * a * l, 1.6 * a * r)
    }
  },
}

// ---- pad ---------------------------------------------------------------------------------------
const track4 = {
  color: '#9fb8ff',
  graph: x => { const p = padAt(x); return p ? p[2].map(n => -1.2 + (n + 24) * 0.03) : null },
  midi: x => { const p = padAt(x); return p && x < END - 8 ? p[2].map(n => 60 + Math.round(n * 100) / 100) : [] },
  formula: ["Pad = \\LP_{f_c(x)}\\,O(f_1 \\ldots f_4),\\quad f_c = 900 + 2600\\,\\tfrac{1 - \\cos(2\\pi x/64)}{2}\\ \\text{— фильтр дышит раз в 64 доли}"],
  audio({ bpm }) {
    const o = organ({ voices: 4, stops: [[1, 1], [2, 0.3], [4, 0.1]], chiff: 0.02, gain: 0.025 })
    const lpL = filter('lp'), lpR = filter('lp'), verb = reverb({ room: 0.95, damp: 0.35, wet: 0.55 })
    return x => {
      const p = padAt(x), fc = 900 + 2600 * (0.5 - 0.5 * Math.cos(TAU * x / 64))
      const [l, r] = o(p && x < END - 8 ? p[2].map(n => hz(n, C4)) : [])
      return verb(lpL(l, fc), lpR(r, fc))
    }
  },
}

// ---- drone -------------------------------------------------------------------------------------
const track5 = {
  color: '#7f8fff',
  graph: x => (x < END - 6 && x > 8 ? -2.6 : null),
  midi: x => (x < END - 6 && x > 8 ? [60 + Math.round(DRONE * 100) / 100] : []),
  formula: ["D = a(x)\\big(\\sin 2\\pi f_0 t + 0.3\\sin 4\\pi f_0 t\\big)\\quad\\text{— основной тон натурального звукоряда (обертоны 8–15 над ним)}"],
  audio() {
    const o1 = osc('sine'), o2 = osc('sine'), level = smooth(3000), f = hz(DRONE, C4)
    return x => {
      const a = level(x > 8 && x < END - 6 ? 1 : 0)
      const y = a * (0.17 * o1(f) + 0.05 * o2(2 * f))
      return [y, y]
    }
  },
}

// ---- wind --------------------------------------------------------------------------------------
const track6 = {
  color: '#7f8fa6',
  graph: x => (x < END ? -2.95 + 0.04 * sin(TAU * x / 8) : null),
  formula: ["W = \\BP_{f(T)}\\eta,\\quad f(T) \\text{ блуждает — ветер}"],
  audio({ bpm }) {
    const sec = 60 / bpm, n = noise(77), bl = filter('bp'), br = filter('bp'), level = smooth(800)
    return x => {
      const t = x * sec, a = level(x < END ? 0.22 : 0), f = 500 * 2 ** (1.3 * sin(TAU * t / 13))
      return [a * bl(n(), f, 3), a * br(n(), f * 1.06, 3)]
    }
  },
}

export default {
  name: 'tidal-fields',
  bpm: 66,
  key: 'C',
  mode: 'harmonic', // Натуральный звукоряд
  length: END,
  theme: 'void',
  style: 'ambient',
  generator: {"style":"ambient","seed":2,"seeds":{"arrangement":2,"melody":15855,"instruments":209461},"length":"normal","mode":"harmonic"},
  parts: ['piano', 'bells', 'glass'],
  sections: SECTIONS,
  tracks: { "piano": track0, "bells": track1, "glass": track2, "choir": track3, "pad": track4, "drone": track5, "wind": track6 },
}
